PREFIX brick: <https://brickschema.org/schema/Brick#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?zone ?sensor ?name WHERE {
  ?sensor a brick:AirTemperatureSensor .
  ?zone brick:hasSubComponent ?sensor .
  OPTIONAL { ?zone rdfs:label ?name }
}

SELECT ?cls (COUNT(*) as ?n) WHERE {
  ?s a ?cls .
} GROUP BY ?cls ORDER BY ?n DESC

SELECT ?cls (COUNT(*) as ?n) WHERE {
  ?s a ?cls .
} GROUP BY ?cls

PREFIX brick: <https://brickschema.org/schema/Brick#>
PREFIX ref: <https://brickschema.org/schema/Brick/ref#>
SELECT ?zone ?sensor ?name ?tsid WHERE {
  ?sensor a brick:Air_Temperature_Sensor .
  ?zone brick:hasSubComponent ?sensor .
  OPTIONAL { ?zone rdfs:label ?name }
  OPTIONAL { ?sensor ref:hasTimeseriesId ?tsid }
}

PREFIX brick: <https://brickschema.org/schema/Brick#>
PREFIX ref: <https://brickschema.org/schema/Brick/ref#>
SELECT ?sensor ?p ?o WHERE {
  ?sensor a brick:Air_Temperature_Sensor .
  ?sensor ?p ?o .
} LIMIT 30

PREFIX brick: <https://brickschema.org/schema/Brick#>
SELECT ?sensor (COUNT(*) as ?n) WHERE {
  ?sensor a brick:Air_Temperature_Sensor .
  ?sensor brick:isPointOf ?loc .
} GROUP BY ?sensor

PREFIX brick: <https://brickschema.org/schema/Brick#>
SELECT DISTINCT ?cls WHERE {
  ?s brick:isPointOf ?loc .
  ?loc a ?cls .
}

PREFIX brick: <https://brickschema.org/schema/Brick#>
SELECT DISTINCT ?room ?loc WHERE {
  ?sensor a brick:Air_Temperature_Sensor .
  ?sensor brick:isPointOf ?room .
  ?room brick:hasSubComponent ?loc .
} LIMIT 30

PREFIX brick: <https://brickschema.org/schema/Brick#>
SELECT DISTINCT ?parent WHERE {
  ?z a brick:HVAC_Zone .
  ?z brick:hasPart ?parent .
}

SELECT ?z ?name WHERE {
  ?z a brick:HVAC_Zone .
  OPTIONAL { ?z rdfs:label ?name }
  ?z brick:hasPart ?room .
} LIMIT 5
